const rows = $input.all().map((item) => item.json);
return [{
  json: {
    source: 'SAPHANADB.T001',
    client: '250',
    count: rows.length,
    rows: rows.map((row) => ({
      companyCode: row.BUKRS,
      companyName: row.BUTXT,
      city: row.ORT01,
      country: row.LAND1,
      currency: row.WAERS,
    })),
  },
}];

const hana = $('Pack HANA Company Codes').first().json.rows;
const payload = $input.first().json;
const odata = payload?.d?.results ?? payload?.value ?? [];
const hanaByCode = new Map(hana.map((row) => [row.companyCode, row]));
const odataByCode = new Map(odata.map((row) => [row.CompanyCode, row]));
const codes = [...new Set([...hanaByCode.keys(), ...odataByCode.keys()])].sort();
return codes.map((companyCode) => {
  const h = hanaByCode.get(companyCode);
  const o = odataByCode.get(companyCode);
  let status = 'MATCH';
  if (!h) status = 'ODATA_ONLY';
  else if (!o) status = 'HANA_ONLY';
  else if (h.companyName !== o.CompanyCodeName || h.country !== o.Country || h.currency !== o.Currency) status = 'DIFFERENT';
  return { json: {
    companyCode,
    hanaName: h?.companyName ?? null,
    odataName: o?.CompanyCodeName ?? null,
    country: o?.Country ?? h?.country ?? null,
    currency: o?.Currency ?? h?.currency ?? null,
    status,
  } };
});
